'use strict';

/**
 * test.js — Unit test for the native_image addon.
 *
 * Validates decode, encode, and LQIP functionality against known test
 * fixtures generated by sharp.  Each test is wrapped in try/catch so
 * a single failure does not halt the suite.
 *
 * Usage: node tests/test.js
 *
 * The native module is loaded from multiple candidate paths.  If none
 * are available the script prints a clear message and tests only the
 * fixture generator (sharp).
 */

const path = require('path');
const sharp = require('sharp');

// ── Helpers ──────────────────────────────────────────────────────────────

let passed = 0;
let failed = 0;
let skipped = 0;

function pass(label, detail) {
  console.log(`  \u2705 ${label}${detail ? ` — ${detail}` : ''}`);
  passed++;
}

function fail(label, reason) {
  console.log(`  \u274C ${label} — ${reason}`);
  failed++;
}

function skip(label, reason) {
  console.log(`  \u26A0\uFE0F ${label} — ${reason}`);
  skipped++;
}

// ── Native module loader ─────────────────────────────────────────────────

function loadNativeModule() {
  const candidates = [
    // Direct build output (most common)
    path.join(__dirname, '..', 'build', 'Release', 'native_image'),
    // With .node extension
    path.join(__dirname, '..', 'build', 'Release', 'native_image.node'),
    // Electron native path (if shipped separately)
    path.join(__dirname, '..', '..', 'electron', 'native', 'native_image'),
    path.join(__dirname, '..', '..', 'electron', 'native', 'native_image.node'),
    // Alternate naming convention
    path.join(__dirname, '..', 'build', 'Release', 'ahg-native-image'),
    path.join(__dirname, '..', 'build', 'Release', 'ahg-native-image.node'),
    path.join(__dirname, '..', '..', 'electron', 'native', 'ahg-native-image'),
    path.join(__dirname, '..', '..', 'electron', 'native', 'ahg-native-image.node'),
  ];

  for (const p of candidates) {
    try {
      const mod = require(p);
      // Verify it looks like our native addon
      if (mod && typeof mod.decodeWebP === 'function') {
        return mod;
      }
    } catch {
      // Try next path
    }
  }
  return null;
}

// ── Test fixture generation ──────────────────────────────────────────────

/** Deterministic pseudo-random RGBA buffer */
function createTestRgba(w, h, seed = 42) {
  const data = Buffer.alloc(w * h * 4);
  let s = seed;
  for (let i = 0; i < w * h * 4; i++) {
    s = (s * 1664525 + 1013904223) & 0x7fffffff;
    data[i] = s & 0xff;
  }
  return data;
}

async function generateFixtures() {
  // WebP fixture: 460×215 (Steam header size)
  const rgba = createTestRgba(460, 215, 1);
  const webpBuf = await sharp(rgba, { raw: { width: 460, height: 215, channels: 4 } })
    .webp({ quality: 85 })
    .toBuffer();

  // JPEG fixture: 100×100
  const jpegRgba = createTestRgba(100, 100, 2);
  const jpegBuf = await sharp(jpegRgba, { raw: { width: 100, height: 100, channels: 4 } })
    .jpeg({ quality: 85 })
    .toBuffer();

  return { webpBuf, jpegBuf, rgba, w: 460, h: 215 };
}

// ── Tests ────────────────────────────────────────────────────────────────

async function run() {
  console.log('=== AHG Native Image Addon Tests ===\n');

  // ── 1. Fixture generator ──
  console.log('─── Fixture Setup ───');

  let fixtures;
  try {
    fixtures = await generateFixtures();
    pass('Test fixtures generated (sharp)',
      `WebP: ${fixtures.webpBuf.length} B, JPEG: ${fixtures.jpegBuf.length} B`);
  } catch (e) {
    fail('Test fixtures generated (sharp)', e.message);
    console.log('\n\u274C Cannot continue without sharp — aborting.\n');
    process.exit(1);
  }

  // ── 2. Native module load ──
  console.log('\n─── Module Load ───');

  const nativeAddon = loadNativeModule();

  if (!nativeAddon) {
    skip('Native module loaded',
      'compile first with: cd native && node-gyp rebuild');
    console.log('\n\u26A0\uFE0F Native module not available — testing only the test fixture generator...\n');

    // Test at least that sharp works
    try {
      const result = await sharp(fixtures.webpBuf)
        .ensureAlpha()
        .raw()
        .toBuffer();
      const meta = await sharp(fixtures.webpBuf).metadata();
      if (Buffer.isBuffer(result) && meta.width && meta.height) {
        pass('Sharp-based decode works as fallback',
          `${meta.width}\u00D7${meta.height}, ${result.length} B`);
      }
    } catch (e) {
      fail('Sharp-based decode works as fallback', e.message);
    }

    const total = passed + failed + skipped;
    console.log(`\n========================================`);
    console.log(`${passed}/${total} tests passed`);
    if (skipped > 0) console.log(`${skipped} skipped`);
    if (failed > 0) console.log(`${failed} FAILED`);
    process.exit(failed > 0 ? 1 : 0);
  }

  pass('Native module loaded');

  // Verify exports
  const expectedExports = ['decodeWebP', 'decodeJPEG', 'encodeWebP', 'generateLQIP', 'batchDecode', 'isGPUSupported'];
  for (const name of expectedExports) {
    if (typeof nativeAddon[name] === 'function') {
      pass(`Export "${name}" is function`);
    } else {
      fail(`Export "${name}" is function`, `got ${typeof nativeAddon[name]}`);
    }
  }

  // ── 3. WebP Decode ──
  console.log('\n─── WebP Decode ───');

  let decodedWebP;
  try {
    decodedWebP = nativeAddon.decodeWebP(fixtures.webpBuf);
    const expectedLen = 460 * 215 * 4;
    const dimOk = decodedWebP.width === 460 && decodedWebP.height === 215;
    const lenOk = Buffer.isBuffer(decodedWebP.data) && decodedWebP.data.length === expectedLen;

    if (dimOk && lenOk) {
      pass('WebP decode: 460\u00D7215 \u2192 RGBA',
        `${decodedWebP.width}\u00D7${decodedWebP.height}, ${decodedWebP.data.length} B`);
    } else {
      fail('WebP decode: 460\u00D7215 \u2192 RGBA',
        `expected ${460}\u00D7${215} / ${expectedLen} B, got ${decodedWebP.width}\u00D7${decodedWebP.height} / ${decodedWebP.data?.length} B`);
    }
  } catch (e) {
    fail('WebP decode: 460\u00D7215 \u2192 RGBA', e.message);
  }

  // ── 4. JPEG Decode ──
  console.log('\n─── JPEG Decode ───');

  try {
    const decodedJpeg = nativeAddon.decodeJPEG(fixtures.jpegBuf);
    const expectedLen = 100 * 100 * 4;
    const dimOk = decodedJpeg.width === 100 && decodedJpeg.height === 100;
    const lenOk = Buffer.isBuffer(decodedJpeg.data) && decodedJpeg.data.length === expectedLen;

    if (dimOk && lenOk) {
      pass('JPEG decode: 100\u00D7100 \u2192 RGBA',
        `${decodedJpeg.width}\u00D7${decodedJpeg.height}, ${decodedJpeg.data.length} B`);
    } else {
      fail('JPEG decode: 100\u00D7100 \u2192 RGBA',
        `expected ${100}\u00D7${100} / ${expectedLen} B, got ${decodedJpeg.width}\u00D7${decodedJpeg.height} / ${decodedJpeg.data?.length} B`);
    }
  } catch (e) {
    fail('JPEG decode: 100\u00D7100 \u2192 RGBA', e.message);
  }

  // ── 5. WebP Encode (roundtrip) ──
  console.log('\n─── WebP Encode ───');

  try {
    const testRgba = createTestRgba(100, 100, 99);
    const encoded = nativeAddon.encodeWebP(testRgba, 100, 100, 85);

    if (Buffer.isBuffer(encoded) && encoded.length > 0) {
      pass('WebP encode: 100\u00D7100 RGBA \u2192 WebP buffer',
        `${encoded.length} B`);

      // Decode back and verify dimensions
      try {
        const roundtrip = nativeAddon.decodeWebP(encoded);
        if (roundtrip.width === 100 && roundtrip.height === 100) {
          pass('WebP encode roundtrip: dimensions preserved',
            `${roundtrip.width}\u00D7${roundtrip.height}`);
        } else {
          fail('WebP encode roundtrip: dimensions preserved',
            `expected 100\u00D7100, got ${roundtrip.width}\u00D7${roundtrip.height}`);
        }
      } catch (e2) {
        fail('WebP encode roundtrip: decode after encode', e2.message);
      }
    } else {
      fail('WebP encode: 100\u00D7100 RGBA \u2192 WebP buffer',
        `expected Buffer, got ${typeof encoded}`);
    }
  } catch (e) {
    fail('WebP encode: 100\u00D7100 RGBA \u2192 WebP buffer', e.message);
  }

  // ── 6. LQIP Generation ──
  console.log('\n─── LQIP Generation ───');

  try {
    const lqip = nativeAddon.generateLQIP(fixtures.rgba, 460, 215, 20);
    if (typeof lqip === 'string' && lqip.startsWith('data:image/webp;base64,')) {
      const b64 = lqip.slice('data:image/webp;base64,'.length);
      pass('LQIP generation',
        `data:image/webp;base64,${b64.substring(0, 20)}... (${b64.length} chars)`);
    } else {
      fail('LQIP generation',
        `expected data URL, got ${typeof lqip} ${lqip?.substring(0, 40)}`);
    }
  } catch (e) {
    fail('LQIP generation', e.message);
  }

  // ── 7. GPU Support ──
  console.log('\n─── GPU Support ───');

  try {
    const supported = nativeAddon.isGPUSupported();
    if (typeof supported === 'boolean') {
      pass('isGPUSupported()',
        supported ? 'GPU acceleration available' : 'no GPU support (software fallback)');
    } else {
      fail('isGPUSupported()', `expected boolean, got ${typeof supported}`);
    }
  } catch (e) {
    fail('isGPUSupported()', e.message);
  }

  // ── 8. Batch Decode ──
  console.log('\n─── Batch Decode ───');

  try {
    const batchInputs = [
      { data: fixtures.webpBuf, type: 'webp' },
      { data: fixtures.jpegBuf, type: 'jpeg' },
      { data: fixtures.webpBuf, type: 'webp' },
    ];
    const batchOut = nativeAddon.batchDecode(batchInputs, 2);

    if (Array.isArray(batchOut) && batchOut.length === 3) {
      let allValid = true;
      for (let i = 0; i < batchOut.length; i++) {
        if (!batchOut[i] || !Buffer.isBuffer(batchOut[i].data) || batchOut[i].index !== i) {
          allValid = false;
          break;
        }
      }
      if (allValid) {
        pass('Batch decode: 3 images',
          `all ${batchOut.length} results valid with correct indices`);
      } else {
        fail('Batch decode: 3 images', 'some results missing data or wrong index');
      }
    } else {
      fail('Batch decode: 3 images',
        `expected array of 3, got ${Array.isArray(batchOut) ? batchOut.length : typeof batchOut}`);
    }
  } catch (e) {
    fail('Batch decode: 3 images', e.message);
  }

  // ── Summary ──
  const total = passed + failed + skipped;
  console.log(`\n========================================`);
  console.log(`${passed}/${total} tests passed`);
  if (skipped > 0) console.log(`${skipped} skipped`);
  if (failed > 0) console.log(`${failed} FAILED`);
  process.exit(failed > 0 ? 1 : 0);
}

run().catch(err => {
  console.error('Fatal error:', err);
  process.exit(1);
});
